"""A STANDARD PDE BENCHMARK: PDEBench's 2-D diffusion-reaction, generated by the engine.

PDEBench (Takamoto et al., NeurIPS 2022 datasets track) is a standard benchmark for neural PDE surrogates. Its 2-D
diffusion-reaction set is FitzHugh-Nagumo on [-1, 1]^2, 128 x 128 cells, t in [0, 5] at 101 frames, Du = 1e-3,
Dv = 5e-3, k = 5e-3, zero-flux walls, u0 and v0 standard normal noise per cell (configs/diff-react.yaml,
src/sim_diff_react.py), integrated by the method of lines with scipy's solve_ivp at its default tolerances (RK45,
rtol 1e-3, atol 1e-6). bench/laws/diff_react.law is the same equations on the same lattice (the same five-point
Laplacian, edges included), the classical RK4 in the law's lets, every z-plane a sample.

  accuracy    each sample against the same method of lines at tight tolerances (DOP853, rtol 1e-10): the spatial
              discretisation is the same, so what differs is time stepping and float32. PDEBench's nRMSE
              (||pred - ref|| / ||ref|| over every frame and both fields), for the engine at its step and at 2x and 4x
              finer (Heun: order 2), and for PDEBench's own recipe (solve_ivp's defaults) against the same reference.
  throughput  samples a second against the batch (z-planes), card time, against the recipe's wall time a sample.
  --hdf5 PATH --samples N   also writes N samples in PDEBench's layout (one group a sample: data (101, 128, 128, 2),
              grid/x, grid/y, grid/t), from seeds 0..N-1.

Writes bench/results/pdebench.{json,md}.

    python bench/pdebench.py [--hdf5 out.h5 --samples 1000]
"""

import argparse
import os
import time
import tempfile

import numpy as np
import scipy.sparse as sp
from scipy.integrate import solve_ivp

from common import BUILD, HERE, lawc, lawc_json, read_state, save, write_scene, write_state

LAW = os.path.join(HERE, "laws", "diff_react.law")
N, T, FRAMES = 128, 5.0, 101
DU, DV, KK = 1e-3, 5e-3, 5e-3
H = 2.0 / N


def initial(seed):
    """PDEBench's: u0 then v0, standard normal, from one generator."""
    rng = np.random.default_rng(seed)
    return rng.standard_normal(N * N).reshape(N, N), rng.standard_normal(N * N).reshape(N, N)


def laplacian():
    """The five-point Laplacian with zero-flux walls (a missing neighbour dropped), as PDEBench builds it."""
    d = np.full(N, -2.0)
    d[[0, -1]] = -1.0
    one = sp.diags([np.ones(N - 1), d, np.ones(N - 1)], [-1, 0, 1]) / (H * H)
    eye = sp.identity(N)
    return (sp.kron(eye, one) + sp.kron(one, eye)).tocsr()


def method_of_lines(u0, v0, rtol, atol, method):
    lap = laplacian()
    n = N * N

    def rhs(_, y):
        u, v = y[:n], y[n:]
        return np.concatenate([DU * (lap @ u) + u - u ** 3 - KK - v, DV * (lap @ v) + u - v])

    t0 = time.perf_counter()
    sol = solve_ivp(rhs, (0.0, T), np.concatenate([u0.ravel(), v0.ravel()]), t_eval=np.linspace(0.0, T, FRAMES),
                    method=method, rtol=rtol, atol=atol)
    secs = time.perf_counter() - t0
    y = sol.y.T  # (frames, 2n)
    return np.stack([y[:, :n].reshape(FRAMES, N, N), y[:, n:].reshape(FRAMES, N, N)], -1), secs


def engine(seeds, work, cfl=0.15, timing=False):
    """Every seed a z-plane; frames (101, 128, 128, 2) a sample. A step is a frame, its substeps by max_dt = cfl h^2 / Dv."""
    refine = 1
    us, vs = zip(*(initial(s) for s in seeds))
    b = len(seeds)
    scene = write_scene(os.path.join(work, f"dr_{b}.scene"), (N, N, b, H), [LAW])
    start = write_state(os.path.join(work, f"dr_init_{b}_{refine}"), {"u": np.stack(us), "v": np.stack(vs)}, H)
    steps = (FRAMES - 1) * refine
    dt = T / steps
    if timing:
        j = lawc_json("--scene", scene, "--init", start, "--steps", "20", "--warmup", "3", "--dt", repr(dt), "--backend", "cuda",
                      "--param", "cfl", repr(cfl))
        return j["gpu_ms"], j["substeps"][0] if j.get("substeps") else None
    out = os.path.join(work, f"dr_out_{b}_{cfl}")
    lawc("--scene", scene, "--init", start, "--steps", str(steps), "--dt", repr(dt), "--backend", "cuda", "--dump", out, "--every", str(refine),
         "--param", "cfl", repr(cfl))
    frames = np.zeros((b, FRAMES, N, N, 2), np.float32)
    for f in range(FRAMES):
        s, _, _ = read_state(os.path.join(out, f"step_{f * refine}"))
        frames[:, f, :, :, 0] = s["u"]
        frames[:, f, :, :, 1] = s["v"]
    return frames


def nrmse(pred, ref):
    return float(np.linalg.norm((pred - ref)[1:]) / np.linalg.norm(ref[1:]))


def write_hdf5(path, count, work, batch=64):
    import h5py
    t = np.linspace(0.0, T, FRAMES)
    x = np.linspace(-1 + H / 2, 1 - H / 2, N)
    t0 = time.perf_counter()
    with h5py.File(path, "w") as f:
        for first in range(0, count, batch):
            seeds = list(range(first, min(count, first + batch)))
            frames = engine(seeds, work)
            for i, s in enumerate(seeds):
                g = f.create_group(f"{s:04d}")
                g.create_dataset("data", data=frames[i])
                g.create_dataset("grid/x", data=x)
                g.create_dataset("grid/y", data=x)
                g.create_dataset("grid/t", data=t)
    return time.perf_counter() - t0


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--hdf5")
    ap.add_argument("--samples", type=int, default=1000)
    args = ap.parse_args()
    seeds = list(range(8))
    out = {"problem": {"n": N, "t": T, "frames": FRAMES, "Du": DU, "Dv": DV, "k": KK}}
    md = ["# A standard benchmark: PDEBench's 2-D diffusion-reaction\n\n"
          f"FitzHugh-Nagumo on [-1, 1]², {N} x {N} cells, t in [0, {T:g}] at {FRAMES} frames, Du = {DU:g}, Dv = {DV:g}, "
          f"k = {KK:g}, zero-flux walls, u0, v0 ~ N(0, 1) per cell: PDEBench's `configs/diff-react.yaml`. The law "
          "(`bench/laws/diff_react.law`) has PDEBench's spatial operator exactly, the classical RK4 in time, a sample a z-plane.\n\n"]
    with tempfile.TemporaryDirectory() as work:
        refs, recipe, recipe_s, tight_s = [], [], [], []
        for s in seeds:
            u0, v0 = initial(s)
            r, secs = method_of_lines(u0, v0, 1e-10, 1e-12, "DOP853")
            p, psecs = method_of_lines(u0, v0, 1e-3, 1e-6, "RK45")
            refs.append(r)
            recipe.append(nrmse(p, r))
            recipe_s.append(psecs)
            tight_s.append(secs)
            print(f"seed {s}: reference {secs:.1f} s, PDEBench recipe {psecs:.1f} s, recipe nRMSE {recipe[-1]:.2e}")
        rows = []
        for cfl in (0.3, 0.15, 0.075):
            frames = engine(seeds, work, cfl)
            errs = [nrmse(frames[i].astype(np.float64), refs[i]) for i in range(len(seeds))]
            sub = int(np.ceil((T / (FRAMES - 1)) / (cfl * H * H / DV)))
            rows.append({"cfl": cfl, "substeps_a_frame": sub, "nrmse_mean": float(np.mean(errs)), "nrmse_max": float(np.max(errs))})
            print(f"engine, cfl {cfl} ({sub} substeps a frame): nRMSE {np.mean(errs):.2e} (worst {np.max(errs):.2e})")
        out["accuracy"] = {"engine": rows, "recipe_nrmse_mean": float(np.mean(recipe)), "recipe_nrmse_max": float(np.max(recipe)),
                           "recipe_seconds": float(np.mean(recipe_s)), "reference_seconds": float(np.mean(tight_s))}
        md.append(f"## Accuracy\n\n{len(seeds)} samples (seeds 0-{len(seeds) - 1}) against the same method of lines at tight "
                  "tolerances (DOP853, rtol 1e-10, float64): the same spatial operator, so what is left is time stepping and "
                  "float32. nRMSE = ||pred - ref|| / ||ref|| over frames 1-100 and both fields.\n\n"
                  "| solver | nRMSE, mean | worst | order in time |\n|---|---|---|---|\n")
        orders = [""] + [f"{np.log(a['nrmse_mean'] / b['nrmse_mean']) / np.log(b['substeps_a_frame'] / a['substeps_a_frame']):.2f}"
                         for a, b in zip(rows[:-1], rows[1:])]
        for r, o in zip(rows, orders):
            md.append(f"| engine, RK4, {r['substeps_a_frame']} substeps a frame (cfl {r['cfl']}) | {r['nrmse_mean']:.2e} | "
                      f"{r['nrmse_max']:.2e} | {o} |\n")
        md.append(f"| PDEBench's recipe: solve_ivp, RK45, rtol 1e-3, atol 1e-6 | {np.mean(recipe):.2e} | {np.max(recipe):.2e} | |\n")
        md.append("\nAt cfl 0.3 the stiffest (checkerboard) diffusion modes sit near the edge of RK4's stability region, so the "
                  "first ratio is not yet the asymptotic order. The throughput below is at cfl 0.15, the recipe's accuracy.\n")

        md.append(f"\n## Throughput\n\nA step is a frame (0.05, its substeps by the law's max_dt). Card time against the batch; "
                  f"PDEBench's recipe takes {np.mean(recipe_s):.1f} s a sample on this CPU (one core, scipy).\n\n"
                  "| samples in one run | cells | card ms a frame | card s a sample (100 frames) | samples a second |\n|---|---|---|---|---|\n")
        scaling = []
        for b in (1, 16, 256, 1024):
            ms, sub = engine(list(range(b)), work, timing=True)
            per = ms * (FRAMES - 1) / 1000.0 / b
            scaling.append({"samples": b, "card_ms_a_frame": ms, "substeps": sub, "seconds_a_sample": per, "samples_a_second": 1.0 / per})
            md.append(f"| {b} | {N * N * b} | {ms:.3f} | {per:.4f} | {1.0 / per:.0f} |\n")
            print(f"batch {b}: {ms:.3f} ms a frame, {1.0 / per:.0f} samples a second")
        out["throughput"] = scaling
        best = max(s["samples_a_second"] for s in scaling)
        md.append(f"\nPDEBench's 1000 samples of this set: {1000 / best:.1f} s of card time on this laptop GPU, against "
                  f"{1000 * np.mean(recipe_s) / 3600:.1f} h of the recipe on one CPU core, with an error "
                  f"{next(r['nrmse_mean'] for r in rows if r['cfl'] == 0.15) / max(np.mean(recipe), 1e-30):.2g}x the recipe's "
                  "own (against the tight reference). The recipe's time is one core's; scipy does not use more.\n")
        if args.hdf5:
            secs = write_hdf5(args.hdf5, args.samples, work)
            out["hdf5"] = {"path": args.hdf5, "samples": args.samples, "seconds": secs}
            md.append(f"\nWrote {args.samples} samples in PDEBench's layout to `{args.hdf5}` in {secs:.0f} s (with the disk).\n")
    save("pdebench", out, "".join(md))


if __name__ == "__main__":
    os.chdir(BUILD)
    main()
